'use strict';

// MODULES //

var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var isCollection = require( '@stdlib/assert/is-collection' );
var hasEqualShape = require( '@stdlib/ndarray/base/assert/has-equal-shape' );
var getShape = require( '@stdlib/ndarray/shape' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var base = require( './base.js' );


// MAIN //

/**
* Copies elements from an input ndarray to an output ndarray and replaces the element at a specified index with a provided value.
*
* @param {ndarray} x - input ndarray
* @param {IntegerArray} indices - indices of the element to replace
* @param {*} value - value to set
* @param {ndarray} out - output ndarray
* @throws {TypeError} first argument must be an ndarray
* @throws {TypeError} second argument must be an array of integers
* @throws {RangeError} second argument must be an array of valid indices
* @throws {RangeError} number of indices must equal the number of input ndarray dimensions
* @throws {TypeError} fourth argument must be an ndarray
* @throws {Error} fourth argument must have the same shape as the first argument
* @returns {ndarray} output ndarray
*
* @example
* var ndarray = require( '@stdlib/ndarray/ctor' );
* var emptyLike = require( '@stdlib/ndarray/empty-like' );
*
* var buffer = [ 1, 2, 3, 4 ];
* var shape = [ 2, 2 ];
* var order = 'row-major';
* var strides = [ 2, 1 ];
* var offset = 0;
*
* var x = ndarray( 'generic', buffer, shape, strides, offset, order );
* var y = emptyLike( x );
*
* var out = assign( x, [ 0, 0 ], 5, y );
* // returns <ndarray>[ [ 5, 2 ], [ 3, 4 ] ]
*
* var bool = ( out === y );
* // returns true
*/
function assign( x, indices, value, out ) {
	var sh;

	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray. Value: `%s`.', x ) );
	}
	if ( !isCollection( indices ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an array of integers. Value: `%s`.', indices ) );
	}
	if ( !isndarrayLike( out ) ) {
		throw new TypeError( format( 'invalid argument. Fourth argument must be an ndarray. Value: `%s`.', out ) );
	}
	sh = getShape( x );
	if ( indices.length !== sh.length ) {
		throw new RangeError( format( 'invalid argument. Number of indices does not match the number of array dimensions. Array shape: (%s). Number of indices: %u.', join( sh, ',' ), indices.length ) );
	}
	if ( !hasEqualShape( x, out ) ) {
		throw new Error( format( 'invalid argument. Fourth argument must have the same shape as the first argument. First argument shape: (%s). Fourth argument shape: (%s).', join( sh, ',' ), join( getShape( out ), ',' ) ) );
	}
	return base( x, indices, value, out );
}


// EXPORTS //

module.exports = assign;
